package com.example.starter.firmware.domain;

/**
 * 设备投放任务，同设备同发布单最多一条。
 *
 * @param id               任务ID
 * @param releaseId        所属发布单ID
 * @param deviceId         设备ID
 * @param status           任务状态
 * @param attempt          接收尝试代次，从1开始；完整性失败后重新拉取加一
 * @param firstResult      首次安装回执结果（SUCCESS/FAILED），未回执为 null；完整性失败不写
 * @param integrityReason  最近一次完整性失败原因代码，PENDING/可安装/已安装时为 null
 * @param installableAtUtc 最近一次判定可安装的 UTC 时刻（ISO-8601），从未可安装为 null
 */
public record RolloutTask(long id, long releaseId, String deviceId, TaskStatus status, int attempt,
                          ReceiptResult firstResult, String integrityReason, String installableAtUtc) {
}

package com.example.starter.firmware.domain;

/**
 * 发布分片登记项（持久化行）。按 seqNo 升序即为规范排序。
 *
 * @param releaseId 所属发布单ID
 * @param seqNo    分片序号，从0开始连续
 * @param digest   分片摘要，64位小写十六进制 SHA-256
 */
public record ReleaseFragment(long releaseId, int seqNo, String digest) {
}

package com.example.starter.firmware.domain;

/**
 * 完整性失败原因代码，可区分失败分支；事件流水与任务状态均只存代码，不拼消息。
 */
public enum IntegrityFailureReason {

    /** 某分片接收摘要与登记摘要不一致。 */
    MISMATCH_DIGEST,

    /** 同序号被重复提交且摘要与首次不同。 */
    DUPLICATE_DIGEST,

    /** 全部分片到齐但聚合摘要与完整包摘要不一致（仅批量提交可能出现）。 */
    AGGREGATE_MISMATCH
}

