void 序号越界400_分片接收幂等同参重放_失败不占键() throws Exception {
    long taskId = registerAndPull("d1", "r1");

    // 越界序号：400，且不占 requestId
    mockMvc.perform(post("/api/tasks/" + taskId + "/fragments").contentType("application/json")
                    .content(fragmentsBody("rf", "5", D0)))
            .andExpect(status().isBadRequest())
            .andExpect(jsonPath("$.code").value("FRAGMENT_SEQ_OUT_OF_RANGE"));

    // 同参重放首次响应（PENDING，已收1片）
    String first = receive(taskId, fragmentsBody("rid", "0", D0));
    String replay = receive(taskId, fragmentsBody("rid", "0", D0));
    assertThat(replay).isEqualTo(first);
    assertThat(jdbc.queryForObject(
            "SELECT COUNT(*) FROM task_fragment_receipt WHERE task_id = ?", Long.class, taskId))
            .isEqualTo(1);

    // 同 requestId 异参：409
    mockMvc.perform(post("/api/tasks/" + taskId + "/fragments").contentType("application/json")
                    .content(fragmentsBody("rid", "1", D1)))
            .andExpect(status().isConflict())
            .andExpect(jsonPath("$.code").value("REQUEST_ID_CONFLICT"));

    // 业务失败（摘要不符）不占键：同 requestId 随后可成功提交正确分片
    mockMvc.perform(post("/api/tasks/" + taskId + "/fragments").contentType("application/json")
                    .content(fragmentsBody("rid2", "1", BAD)))
            .andExpect(status().isOk());
    String retried = receive(taskId, fragmentsBody("rid2", "1", D1));
    // 代次已因错误提交失败，正确分片必须重新拉取建立新代次后才能提交
    assertThat(com.jayway.jsonpath.JsonPath.read(retried, "$.task.status"))
            .isEqualTo("INTEGRITY_FAILED");
    assertThat(com.jayway.jsonpath.JsonPath.read(retried, "$.code")).isNull();
}

